mapper.select:
SELECT EXISTS(
    SELECT 1
    FROM socials
    WHERE follower_id = #{followerId}
      AND vlogger_id = #{vloggerId}
)

mapper.delete:
DELETE FROM socials
WHERE follower_id = #{followerId}
  AND vlogger_id = #{vloggerId}

mapper.select:
