SELECT a.id, a.username, a.avatar_url, a.bio
FROM socials s
INNER JOIN accounts a ON a.id = s.follower_id
WHERE s.vlogger_id = #{vloggerId}
ORDER BY s.id DESC
LIMIT #{limit}

